css:
@font-face {
  font-family: "College Solid";
  src: url("data:font/ttf;base64,") format("truetype");
  font-weight: 400 800;
  font-style: normal;
  font-display: swap;
  unicode-range: U+0020, U+0027, U+002C-002E, U+0030-0039, U+0041-005A, U+0061-007A;
}
#dyn-message-theme[data-theme="message-ticket"] {
  --red: var(--primary, #e23c12);
  --mat: color-mix(in srgb, var(--background, #f3eee4) 82%, #fff);
  --paper-img: url("data:image/jpeg;base64,");
  --grunge: url("data:image/jpeg;base64,");
  --grunge-ink: url("data:image/jpeg;base64,");
  --caption-grit: url("data:image/png;base64,");
  --swoosh: url("message-ticket-swoosh.png");
  background: var(--background, #f3eee4);
  color: var(--secondary, #14110e);
  overflow: hidden;
}
#dyn-message-theme[data-theme="message-ticket"] .defs,
#dyn-message-theme[data-theme="message-ticket"] .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}
#dyn-message-theme[data-theme="message-ticket"] .tk {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
#dyn-message-theme[data-theme="message-ticket"] .bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  background: var(--background, #f3eee4);
  opacity: 0;
}
#dyn-message-theme[data-theme="message-ticket"] .sky {
  position: absolute;
  inset: 0;
  background-color: var(--background, #f3eee4);
  background-image: var(--paper-img);
  background-size: cover;
  background-position: center;
  transform-origin: 50% 70%;
  will-change: transform;
  transform: scale(1);
}
#dyn-message-theme[data-theme="message-ticket"].on .sky {
  animation: tk-zoom 18s linear forwards;
}
#dyn-message-theme[data-theme="message-ticket"][data-motion="slow"].on .sky { animation-duration: 26s; }
#dyn-message-theme[data-theme="message-ticket"][data-motion="fizz"].on .sky { animation-duration: 11s; }
#dyn-message-theme[data-theme="message-ticket"] .chrome {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
}
#dyn-message-theme[data-theme="message-ticket"] .chrome .dot {
  position: absolute;
  fill: var(--secondary, #14110e);
  opacity: 0.88;
}
#dyn-message-theme[data-theme="message-ticket"] .d1 { left: 44cqw; top: 2.2cqh; width: 1.5cqh; height: 1.5cqh; }
#dyn-message-theme[data-theme="message-ticket"] .d2 { left: 47.2cqw; top: 2.1cqh; width: 1.5cqh; height: 1.5cqh; }
#dyn-message-theme[data-theme="message-ticket"] .d3 { left: 68.6cqw; top: 1.8cqh; width: 1.35cqh; height: 1.35cqh; }
#dyn-message-theme[data-theme="message-ticket"] .d4 { left: 71.2cqw; top: 1.8cqh; width: 1.35cqh; height: 1.35cqh; }
#dyn-message-theme[data-theme="message-ticket"] .d5 { left: 72.4cqw; top: 83.6cqh; width: 1.3cqh; height: 1.3cqh; fill: var(--red); }
#dyn-message-theme[data-theme="message-ticket"] .d6 { left: 75.2cqw; top: 83.6cqh; width: 1.3cqh; height: 1.3cqh; fill: var(--red); }
#dyn-message-theme[data-theme="message-ticket"] .slash {
  position: absolute;
  top: 0.7cqh;
  left: 73.6cqw;
  font: 700 3.1cqh/1 "Oswald", "Arial Narrow", sans-serif;
  color: var(--secondary, #14110e);
  transform: rotate(-18deg);
}
#dyn-message-theme[data-theme="message-ticket"] .slash.b { left: 75.2cqw; }
#dyn-message-theme[data-theme="message-ticket"] .gn {
  position: absolute;
  top: 1.15cqh;
  left: 77.4cqw;
  font: 600 1.55cqh/1 "Oswald", "Arial Narrow", sans-serif;
  letter-spacing: 0.16em;
  color: var(--secondary, #14110e);
}
#dyn-message-theme[data-theme="message-ticket"] .serial {
  position: absolute;
  top: 1.2cqh;
  right: 2.4cqw;
  font: 600 1.45cqh/1 "Oswald", "Arial Narrow", sans-serif;
  letter-spacing: 0.14em;
  color: var(--secondary, #14110e);
}
#dyn-message-theme[data-theme="message-ticket"] .date {
  position: absolute;
  right: 10.6cqw;
  bottom: 13.2cqh;
  font: 600 1.55cqh/1 "Oswald", "Arial Narrow", sans-serif;
  letter-spacing: 0.22em;
  color: var(--secondary, #14110e);
}
#dyn-message-theme[data-theme="message-ticket"] .bar-r {
  position: absolute;
  right: 2.2cqw;
  bottom: 12.8cqh;
  width: 7.4cqw;
  height: 2.4cqh;
  background: repeating-linear-gradient(
    90deg,
    var(--secondary, #14110e) 0 0.16cqw,
    transparent 0.16cqw 0.3cqw,
    var(--secondary, #14110e) 0.3cqw 0.38cqw,
    transparent 0.38cqw 0.58cqw
  );
}
#dyn-message-theme[data-theme="message-ticket"] .edge {
  display: none;
}
#dyn-message-theme[data-theme="message-ticket"] .stub {
  --tan: #f3eee4;
  --hole: 1.15cqh;
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 12.8cqw;
  z-index: 4;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  padding: 3.4cqh 0.2cqw 1.8cqh 1.35cqw;
  color: var(--tan);
  opacity: 0;
  transform: translateX(-12cqw);
}
#dyn-message-theme[data-theme="message-ticket"] .stub::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background-color: var(--red);
  background-image: var(--grunge);
  background-size: cover;
  background-position: 22% 40%;
  background-repeat: no-repeat;
  background-blend-mode: screen;
  -webkit-mask-image: radial-gradient(circle at 0 50%, transparent var(--hole), #000 calc(var(--hole) + 0.04cqh));
  -webkit-mask-size: 100% calc(var(--hole) * 4);
  -webkit-mask-repeat: repeat-y;
  mask-image: radial-gradient(circle at 0 50%, transparent var(--hole), #000 calc(var(--hole) + 0.04cqh));
  mask-size: 100% calc(var(--hole) * 4);
  mask-repeat: repeat-y;
}
#dyn-message-theme[data-theme="message-ticket"] .stub > * {
  position: relative;
  z-index: 1;
}
#dyn-message-theme[data-theme="message-ticket"] .perf {
  display: none;
}
#dyn-message-theme[data-theme="message-ticket"] .blk {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  font-family: "Oswald", "Arial Narrow", sans-serif;
  text-transform: uppercase;
  color: var(--tan);
  line-height: 0.84;
}
#dyn-message-theme[data-theme="message-ticket"] .blk em,
#dyn-message-theme[data-theme="message-ticket"] .blk b,
#dyn-message-theme[data-theme="message-ticket"] .stub-code em {
  -webkit-text-fill-color: transparent;
  background-color: var(--tan);
  background-image: var(--grunge-ink);
  background-size: 9.2cqw auto;
  background-repeat: repeat;
  background-blend-mode: multiply;
  -webkit-background-clip: text;
  background-clip: text;
}
#dyn-message-theme[data-theme="message-ticket"] .blk em {
  font-style: normal;
  font-family: "Oswald", "Arial Narrow", sans-serif;
  font-weight: 500;
  font-size: 2.7cqh;
  letter-spacing: 0.1em;
}
#dyn-message-theme[data-theme="message-ticket"] .blk b {
  font-family: "College Solid", "Alumni Sans", "Anton", Impact, sans-serif;
  font-weight: 400;
  font-size: 10.8cqh;
  letter-spacing: 0.02em;
  margin-top: 0.05cqh;
}
#dyn-message-theme[data-theme="message-ticket"] .blk.night {
  gap: 0.7cqh;
}
#dyn-message-theme[data-theme="message-ticket"] .blk.night em {
  font-size: 5.3cqh;
  letter-spacing: 0.08em;
  font-weight: 500;
  line-height: 0.9;
}
#dyn-message-theme[data-theme="message-ticket"] .sep {
  width: 1.7cqh;
  height: 1.7cqh;
  fill: var(--tan);
  flex: 0 0 auto;
}
#dyn-message-theme[data-theme="message-ticket"] .stub-code {
  width: 82%;
  margin-top: 0.2cqh;
}
#dyn-message-theme[data-theme="message-ticket"] .stub-code i {
  display: block;
  height: 4.4cqh;
  background: repeating-linear-gradient(
    90deg,
    var(--secondary, #14110e) 0 0.13cqw,
    transparent 0.13cqw 0.26cqw,
    var(--secondary, #14110e) 0.26cqw 0.48cqw,
    transparent 0.48cqw 0.62cqw
  );
}
#dyn-message-theme[data-theme="message-ticket"] .stub-code em {
  display: block;
  margin-top: 0.55cqh;
  font: 400 1.55cqh/1 "College Solid", "Alumni Sans", "Anton", Impact, sans-serif;
  letter-spacing: 0.06em;
  font-style: normal;
  color: var(--tan);
  text-align: center;
}
#dyn-message-theme[data-theme="message-ticket"] .card {
  position: absolute;
  left: 13.2cqw;
  top: 6.2cqh;
  width: 29.2cqw;
  height: 74.5cqh;
  z-index: 8;
  opacity: 0;
  transform: translateX(-14cqw) rotate(-8deg);
  filter: drop-shadow(0.4cqw 1.4cqh 1.6cqh rgba(20, 16, 12, 0.28));
}
#dyn-message-theme[data-theme="message-ticket"] .polaroid {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 1.9cqh 1.7cqw 2.8cqh;
  background-color: var(--background, #f3eee4);
  background-image: none;
  border-radius: 0.85cqh;
  box-shadow:
    inset 0 0 0 0.1cqh rgba(255, 255, 255, 0.28),
    0 0.2cqh 0.4cqh rgba(20, 16, 12, 0.12);
  transform-origin: 50% 50%;
  overflow: hidden;
  isolation: isolate;
}
#dyn-message-theme[data-theme="message-ticket"] .polaroid::before {
  display: none;
}
#dyn-message-theme[data-theme="message-ticket"] .polaroid::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: inherit;
  background-color: #000;
  mix-blend-mode: multiply;
  opacity: 0.58;
  -webkit-mask-image: var(--grunge);
  -webkit-mask-size: 34% auto;
  -webkit-mask-position: 0 0;
  -webkit-mask-repeat: repeat;
  -webkit-mask-source-type: luminance;
  mask-image: var(--grunge);
  mask-size: 34% auto;
  mask-position: 0 0;
  mask-repeat: repeat;
  mask-mode: luminance;
}
#dyn-message-theme[data-theme="message-ticket"] .polaroid img {
  position: relative;
  z-index: 1;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center top;
  background: #2a241c;
}
#dyn-message-theme[data-theme="message-ticket"] .copy {
  position: absolute;
  left: 44cqw;
  right: 3.6cqw;
  top: 5cqh;
  height: 64cqh;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 0;
  opacity: 0;
  transform: translateX(-10cqw);
}
#dyn-message-theme[data-theme="message-ticket"] .marks {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
#dyn-message-theme[data-theme="message-ticket"] .mk { position: absolute; color: var(--red); fill: var(--red); }
#dyn-message-theme[data-theme="message-ticket"] .mk.star.a { left: -1.6cqw; top: 8cqh; width: 2.4cqh; height: 2.4cqh; }
#dyn-message-theme[data-theme="message-ticket"] .mk.star.b { right: 1cqw; top: 18cqh; width: 2.1cqh; height: 2.1cqh; }
#dyn-message-theme[data-theme="message-ticket"] .mk.star.c { left: 6cqw; bottom: 4cqh; width: 1.8cqh; height: 1.8cqh; }
#dyn-message-theme[data-theme="message-ticket"] .mk.plus {
  font: 700 2.4cqh/1 "Oswald", sans-serif;
}
#dyn-message-theme[data-theme="message-ticket"] .mk.plus.p1 { left: -0.4cqw; top: 22cqh; }
#dyn-message-theme[data-theme="message-ticket"] .mk.plus.p2 { right: 3cqw; top: 6cqh; }
#dyn-message-theme[data-theme="message-ticket"] .mk.tick {
  width: 2.6cqw;
  height: 0.28cqh;
  background: var(--red);
  border-radius: 0.2cqh;
  transform: rotate(-12deg);
}
#dyn-message-theme[data-theme="message-ticket"] .mk.tick.t1 { right: 8cqw; top: 4.4cqh; }
#dyn-message-theme[data-theme="message-ticket"] .mk.tick.t2 { left: 2cqw; bottom: 10cqh; width: 3.4cqw; transform: rotate(8deg); }
#dyn-message-theme[data-theme="message-ticket"] .mk.tick.t3 { right: 12cqw; bottom: 2cqh; transform: rotate(-18deg); }
#dyn-message-theme[data-theme="message-ticket"] .say {
  position: relative;
  z-index: 1;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  transform: rotate(-5deg);
  transform-origin: 50% 55%;
}
#dyn-message-theme[data-theme="message-ticket"] .lines,
#dyn-message-theme[data-theme="message-ticket"] .lines .sym {
  width: 100%;
  text-align: center;
  font-family: "College Solid", "Alumni Sans", "Anton", Impact, "Arial Narrow", sans-serif;
  font-weight: 800;
  font-size: 12.6cqh;
  line-height: 0.88;
  letter-spacing: 0.01em;
  text-transform: uppercase;
  color: var(--secondary, #14110e);
  white-space: normal;
  -webkit-text-fill-color: transparent;
  background-image:
    var(--caption-grit),
    linear-gradient(var(--secondary, #14110e), var(--secondary, #14110e));
  background-size: 32cqw auto, 100% 100%;
  background-position: 0 0, 0 0;
  background-repeat: repeat, no-repeat;
  -webkit-background-clip: text;
  background-clip: text;
}
#dyn-message-theme[data-theme="message-ticket"] .lines .sym {
  font-family: "Alumni Sans", "Anton", Impact, sans-serif;
  font-style: normal;
}
#dyn-message-theme[data-theme="message-ticket"] .hero-wrap {
  position: relative;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-top: 0.4cqh;
}
#dyn-message-theme[data-theme="message-ticket"] .hero {
  position: relative;
  width: 100%;
  text-align: center;
  font-family: "Permanent Marker", "Comic Sans MS", cursive;
  font-size: 20cqh;
  line-height: 0.86;
  letter-spacing: 0.01em;
  text-transform: uppercase;
  color: var(--primary, #e23c12);
  -webkit-text-fill-color: transparent;
  background-image:
    var(--caption-grit),
    linear-gradient(var(--primary, #e23c12), var(--primary, #e23c12));
  background-size: 32cqw auto, 100% 100%;
  background-position: 0 0, 0 0;
  background-repeat: repeat, no-repeat;
  -webkit-background-clip: text;
  background-clip: text;
}
#dyn-message-theme[data-theme="message-ticket"] .swoosh {
  display: block;
  width: 78%;
  height: 7.2cqh;
  margin-top: -0.2cqh;
  background-color: var(--primary, #e23c12);
  -webkit-mask-image: var(--swoosh);
  -webkit-mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-image: var(--swoosh);
  mask-size: contain;
  mask-repeat: no-repeat;
  mask-position: center;
}
#dyn-message-theme[data-theme="message-ticket"] .plate {
  position: absolute;
  left: 42.4cqw;
  right: 0;
  top: 71.2cqh;
  height: 13.2cqh;
  z-index: 7;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.1cqw;
  padding: 0.35cqh 3.2cqw;
  background: none;
  transform: scaleX(0);
  transform-origin: 50% 50%;
}
#dyn-message-theme[data-theme="message-ticket"] .plate::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background-color: var(--secondary, #14110e);
  background-image: var(--grunge);
  background-size: cover;
  background-position: 70% 55%;
  background-repeat: no-repeat;
  background-blend-mode: screen;
  --punch: 0.62cqh;
  -webkit-mask-image:
    linear-gradient(#000 0 0),
    radial-gradient(circle at 0 50%, #000 var(--punch), transparent calc(var(--punch) + 0.04cqh)),
    radial-gradient(circle at 100% 50%, #000 var(--punch), transparent calc(var(--punch) + 0.04cqh));
  -webkit-mask-size: 100% 100%, 100% 20%, 100% 20%;
  -webkit-mask-repeat: no-repeat, repeat-y, repeat-y;
  -webkit-mask-composite: xor, xor;
  mask-image:
    linear-gradient(#000 0 0),
    radial-gradient(circle at 0 50%, #000 var(--punch), transparent calc(var(--punch) + 0.04cqh)),
    radial-gradient(circle at 100% 50%, #000 var(--punch), transparent calc(var(--punch) + 0.04cqh));
  mask-size: 100% 100%, 100% 20%, 100% 20%;
  mask-repeat: no-repeat, repeat-y, repeat-y;
  mask-composite: exclude, exclude;
}
#dyn-message-theme[data-theme="message-ticket"] .plate::after {
  display: none;
}
#dyn-message-theme[data-theme="message-ticket"] .plate > * {
  position: relative;
  z-index: 2;
}
#dyn-message-theme[data-theme="message-ticket"] .name-box {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
#dyn-message-theme[data-theme="message-ticket"] .name-box > span {
  display: block;
  width: 100%;
  white-space: nowrap;
  text-align: center;
  font-family: "College Solid", "Alumni Sans", "Anton", Impact, "Arial Narrow", sans-serif;
  font-weight: 800;
  font-size: 7.6cqh;
  line-height: 1;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: #f6f1e8;
}
#dyn-message-theme[data-theme="message-ticket"] .name-box .sym {
  font-family: "Alumni Sans", "Anton", Impact, sans-serif;
  font-weight: 800;
  font-style: normal;
}
#dyn-message-theme[data-theme="message-ticket"] .star-pop {
  display: flex;
  flex: 0 0 5.8cqh;
  width: 5.8cqh;
  justify-content: center;
  align-items: center;
  transform: scale(0);
}
#dyn-message-theme[data-theme="message-ticket"] .star-pop svg {
  width: 5.6cqh;
  height: 5.6cqh;
  fill: var(--red);
}
#dyn-message-theme[data-theme="message-ticket"] .logo-slot,
#dyn-message-theme[data-theme="message-ticket"] .qr-slot {
  position: absolute;
  z-index: 9;
  width: 10cqw;
  min-width: 8.4cqh;
}
#dyn-message-theme[data-theme="message-ticket"] .logo-slot { top: 3.2cqh; left: 13.6cqw; }
#dyn-message-theme[data-theme="message-ticket"] .qr-slot { right: 2.4cqw; bottom: 16cqh; }

#dyn-message-theme[data-theme="message-ticket"].no-photo .card { display: none; }
#dyn-message-theme[data-theme="message-ticket"].no-photo .copy { left: 16cqw; }
#dyn-message-theme[data-theme="message-ticket"].no-photo .plate { left: 16cqw; }
#dyn-message-theme[data-theme="message-ticket"].no-copy .copy { display: none; }
#dyn-message-theme[data-theme="message-ticket"].no-name .plate { display: none; }
#dyn-message-theme[data-theme="message-ticket"].no-line .lines { display: none; }
#dyn-message-theme[data-theme="message-ticket"].no-hero .hero-wrap { display: none; }

#dyn-message-theme[data-theme="message-ticket"][data-photo-style="bw"] .polaroid img { filter: grayscale(1) contrast(1.08); }
#dyn-message-theme[data-theme="message-ticket"][data-photo-style="color"] .polaroid img { filter: contrast(1.04) saturate(1.06); }
#dyn-message-theme[data-theme="message-ticket"][data-photo-style="sepia"] .polaroid img { filter: sepia(0.7) contrast(1.05); }

#dyn-message-theme[data-theme="message-ticket"].on .bg {
  animation: tk-fade calc(var(--reveal-ms, 1600ms) * 0.42) ease both;
}
#dyn-message-theme[data-theme="message-ticket"].on .stub {
  animation: tk-slide calc(var(--reveal-ms, 1600ms) * 0.48) cubic-bezier(0.16, 1, 0.3, 1) 0.04s both;
}
#dyn-message-theme[data-theme="message-ticket"].on .card {
  animation: tk-card-in calc(var(--reveal-ms, 1600ms) * 0.58) cubic-bezier(0.16, 1, 0.3, 1) 0.1s both;
}
#dyn-message-theme[data-theme="message-ticket"].on .polaroid {
  animation: tk-poster 3.4s steps(1) 1.05s infinite;
}
#dyn-message-theme[data-theme="message-ticket"].on .copy {
  animation: tk-slide calc(var(--reveal-ms, 1600ms) * 0.5) cubic-bezier(0.16, 1, 0.3, 1) 0.2s both;
}
#dyn-message-theme[data-theme="message-ticket"].on .plate {
  animation: tk-plate calc(var(--reveal-ms, 1600ms) * 0.38) cubic-bezier(0.16, 1, 0.3, 1) 0.4s both;
}
#dyn-message-theme[data-theme="message-ticket"].on .star-pop {
  animation: tk-star-pop 0.52s cubic-bezier(0.34, 1.45, 0.64, 1) 0.58s both;
}
#dyn-message-theme[data-theme="message-ticket"][data-motion="slow"].on .stub,
#dyn-message-theme[data-theme="message-ticket"][data-motion="slow"].on .card,
#dyn-message-theme[data-theme="message-ticket"][data-motion="slow"].on .copy,
#dyn-message-theme[data-theme="message-ticket"][data-motion="slow"].on .plate {
  animation-duration: 1.15s;
}
#dyn-message-theme[data-theme="message-ticket"][data-motion="fizz"].on .polaroid {
  animation-duration: 2.1s;
}
#dyn-message-theme[data-theme="message-ticket"][data-motion="slow"].on .polaroid {
  animation-duration: 4.6s;
